     1→// Phase 1: .flmd (FV-Lang Markdown) Parser
     2→// Token 및 AST 정의
     3→
     4→// ============================================================================
     5→// Token Types
     6→// ============================================================================
     7→
     8→enum TokenType {
     9→    // 마크다운 토큰
    10→    Markdown,      // 일반 마크다운 텍스트
    11→    Heading1,      // # 제목
    12→    Heading2,      // ## 소제목
    13→    Heading3,      // ### 세번째 제목
    14→    Paragraph,     // 일반 단락
    15→    ListItem,      // - 항목
    16→
    17→    // 코드 블록
    18→    CodeBlockStart,  // ```fvlang
    19→    CodeBlockEnd,    // ```
    20→    CodeLine,        // 코드 줄
    21→
    22→    // 출력 블록
    23→    OutputBlockStart, // ```output
    24→    OutputBlockEnd,   // ```
    25→    OutputLine,       // 출력 줄
    26→
    27→    // 특수
    28→    Blank,            // 빈 줄
    29→    EOF               // 파일 끝
    30→}
    31→
    32→struct Token {
    33→    type: TokenType,
    34→    content: String,
    35→    line: i32,
    36→    column: i32
    37→}
    38→
    39→// ============================================================================
    40→// AST (Abstract Syntax Tree) 정의
    41→// ============================================================================
    42→
    43→enum BlockType {
    44→    MarkdownText(String),
    45→    Heading(i32, String),     // level, content
    46→    Paragraph(String),
    47→    CodeBlock(String),         // FV-Lang 코드
    48→    OutputBlock(String),       // 예상 출력
    49→    ListBlock(Vec<String>)     // 리스트 항목들
    50→}
    51→
    52→struct Document {
    53→    title: String,
    54→    blocks: Vec<BlockType>,
    55→    metadata: Metadata
    56→}
    57→
    58→struct Metadata {
    59→    version: String,
    60→    created: String,
    61→    modified: String
    62→}
    63→
    64→// ============================================================================
    65→// Lexer (문자열 → 토큰)
    66→// ============================================================================
    67→
    68→fn tokenize(content: String) -> Vec<Token> {
    69→    let mut tokens = Vec::new()
    70→    let lines = content.split('\n')
    71→    let mut line_num = 1
    72→    let mut in_code_block = false
    73→    let mut in_output_block = false
    74→
    75→    for line in lines {
    76→        // 코드 블록 시작/종료
    77→        if line.starts_with("```fvlang") {
    78→            tokens.push(Token {
    79→                type: TokenType::CodeBlockStart,
    80→                content: line.to_string(),
    81→                line: line_num,
    82→                column: 0
    83→            })
    84→            in_code_block = true
    85→        } else if line.starts_with("```output") {
    86→            tokens.push(Token {
    87→                type: TokenType::OutputBlockStart,
    88→                content: line.to_string(),
    89→                line: line_num,
    90→                column: 0
    91→            })
    92→            in_output_block = true
    93→        } else if line.starts_with("```") && (in_code_block || in_output_block) {
    94→            if in_code_block {
    95→                tokens.push(Token {
    96→                    type: TokenType::CodeBlockEnd,
    97→                    content: "```".to_string(),
    98→                    line: line_num,
    99→                    column: 0
   100→                })
   101→                in_code_block = false
   102→            } else {
   103→                tokens.push(Token {
   104→                    type: TokenType::OutputBlockEnd,
   105→                    content: "```".to_string(),
   106→                    line: line_num,
   107→                    column: 0
   108→                })
   109→                in_output_block = false
   110→            }
   111→        }
   112→        // 코드 블록 내 줄
   113→        else if in_code_block {
   114→            tokens.push(Token {
   115→                type: TokenType::CodeLine,
   116→                content: line.to_string(),
   117→                line: line_num,
   118→                column: 0
   119→            })
   120→        }
   121→        // 출력 블록 내 줄
   122→        else if in_output_block {
   123→            tokens.push(Token {
   124→                type: TokenType::OutputLine,
   125→                content: line.to_string(),
   126→                line: line_num,
   127→                column: 0
   128→            })
   129→        }
   130→        // 마크다운 토큰
   131→        else if line.starts_with("# ") {
   132→            tokens.push(Token {
   133→                type: TokenType::Heading1,
   134→                content: line[2..].to_string(),
   135→                line: line_num,
   136→                column: 0
   137→            })
   138→        } else if line.starts_with("## ") {
   139→            tokens.push(Token {
   140→                type: TokenType::Heading2,
   141→                content: line[3..].to_string(),
   142→                line: line_num,
   143→                column: 0
   144→            })
   145→        } else if line.starts_with("### ") {
   146→            tokens.push(Token {
   147→                type: TokenType::Heading3,
   148→                content: line[4..].to_string(),
   149→                line: line_num,
   150→                column: 0
   151→            })
   152→        } else if line.starts_with("- ") {
   153→            tokens.push(Token {
   154→                type: TokenType::ListItem,
   155→                content: line[2..].to_string(),
   156→                line: line_num,
   157→                column: 0
   158→            })
   159→        } else if line.is_empty() {
   160→            tokens.push(Token {
   161→                type: TokenType::Blank,
   162→                content: "".to_string(),
   163→                line: line_num,
   164→                column: 0
   165→            })
   166→        } else {
   167→            tokens.push(Token {
   168→                type: TokenType::Paragraph,
   169→                content: line.to_string(),
   170→                line: line_num,
   171→                column: 0
   172→            })
   173→        }
   174→
   175→        line_num = line_num + 1
   176→    }
   177→
   178→    tokens.push(Token {
   179→        type: TokenType::EOF,
   180→        content: "".to_string(),
   181→        line: line_num,
   182→        column: 0
   183→    })
   184→
   185→    tokens
   186→}
   187→
   188→// ============================================================================
   189→// Parser (토큰 → AST)
   190→// ============================================================================
   191→
   192→fn parse(content: String) -> Result<Document, String> {
   193→    let tokens = tokenize(content)
   194→    let mut blocks = Vec::new()
   195→    let mut i = 0
   196→    let mut title = "Untitled".to_string()
   197→
   198→    while i < tokens.len() {
   199→        let token = &tokens[i]
   200→
   201→        match token.type {
   202→            TokenType::Heading1 => {
   203→                if i == 0 {
   204→                    title = token.content.clone()
   205→                }
   206→                blocks.push(BlockType::Heading(1, token.content.clone()))
   207→                i = i + 1
   208→            }
   209→            TokenType::Heading2 => {
   210→                blocks.push(BlockType::Heading(2, token.content.clone()))
   211→                i = i + 1
   212→            }
   213→            TokenType::Heading3 => {
   214→                blocks.push(BlockType::Heading(3, token.content.clone()))
   215→                i = i + 1
   216→            }
   217→            TokenType::Paragraph => {
   218→                blocks.push(BlockType::Paragraph(token.content.clone()))
   219→                i = i + 1
   220→            }
   221→            TokenType::CodeBlockStart => {
   222→                i = i + 1
   223→                let mut code_lines = Vec::new()
   224→                while i < tokens.len() && tokens[i].type != TokenType::CodeBlockEnd {
   225→                    if tokens[i].type == TokenType::CodeLine {
   226→                        code_lines.push(tokens[i].content.clone())
   227→                    }
   228→                    i = i + 1
   229→                }
   230→                let code = code_lines.join("\n")
   231→                blocks.push(BlockType::CodeBlock(code))
   232→                i = i + 1  // skip closing ```
   233→            }
   234→            TokenType::OutputBlockStart => {
   235→                i = i + 1
   236→                let mut output_lines = Vec::new()
   237→                while i < tokens.len() && tokens[i].type != TokenType::OutputBlockEnd {
   238→                    if tokens[i].type == TokenType::OutputLine {
   239→                        output_lines.push(tokens[i].content.clone())
   240→                    }
   241→                    i = i + 1
   242→                }
   243→                let output = output_lines.join("\n")
   244→                blocks.push(BlockType::OutputBlock(output))
   245→                i = i + 1  // skip closing ```
   246→            }
   247→            TokenType::ListItem => {
   248→                let mut items = Vec::new()
   249→                while i < tokens.len() && tokens[i].type == TokenType::ListItem {
   250→                    items.push(tokens[i].content.clone())
   251→                    i = i + 1
   252→                }
   253→                blocks.push(BlockType::ListBlock(items))
   254→            }
   255→            TokenType::Blank => {
   256→                i = i + 1
   257→            }
   258→            TokenType::EOF => {
   259→                break
   260→            }
   261→            _ => {
   262→                i = i + 1
   263→            }
   264→        }
   265→    }
   266→
   267→    Ok(Document {
   268→        title: title,
   269→        blocks: blocks,
   270→        metadata: Metadata {
   271→            version: "0.1.0".to_string(),
   272→            created: "2026-03-18".to_string(),
   273→            modified: "2026-03-18".to_string()
   274→        }
   275→    })
   276→}
   277→
   278→// ============================================================================
   279→// Validator (AST 검증)
   280→// ============================================================================
   281→
   282→fn validate(doc: Document) -> Result<Document, String> {
   283→    // 기본 검증
   284→    if doc.title.is_empty() {
   285→        return Err("Document title cannot be empty".to_string())
   286→    }
   287→
   288→    if doc.blocks.is_empty() {
   289→        return Err("Document must contain at least one block".to_string())
   290→    }
   291→
   292→    // 코드 블록 뒤에 출력 블록이 오는지 검증 (선택사항)
   293→    let mut prev_code = false
   294→    for block in &doc.blocks {
   295→        match block {
   296→            BlockType::CodeBlock(_) => prev_code = true,
   297→            BlockType::OutputBlock(_) => prev_code = false,
   298→            _ => {}
   299→        }
   300→    }
   301→
   302→    Ok(doc)
   303→}
   304→
   305→// ============================================================================
   306→// Public API
   307→// ============================================================================
   308→
   309→fn parse_flmd(content: String) -> Result<Document, String> {
   310→    let doc = parse(content)?
   311→    validate(doc)
   312→}
   313→
   314→fn document_to_string(doc: Document) -> String {
   315→    let mut output = String::new()
   316→    output.push_str(&format!("# {}\n\n", doc.title))
   317→
   318→    for block in doc.blocks {
   319→        match block {
   320→            BlockType::Heading(level, content) => {
   321→                let heading = "#".repeat(level as usize)
   322→                output.push_str(&format!("{} {}\n\n", heading, content))
   323→            }
   324→            BlockType::Paragraph(content) => {
   325→                output.push_str(&format!("{}\n\n", content))
   326→            }
   327→            BlockType::CodeBlock(code) => {
   328→                output.push_str("```fvlang\n")
   329→                output.push_str(&code)
   330→                output.push_str("\n```\n\n")
   331→            }
   332→            BlockType::OutputBlock(output_content) => {
   333→                output.push_str("```output\n")
   334→                output.push_str(&output_content)
   335→                output.push_str("\n```\n\n")
   336→            }
   337→            BlockType::ListBlock(items) => {
   338→                for item in items {
   339→                    output.push_str(&format!("- {}\n", item))
   340→                }
   341→                output.push_str("\n")
   342→            }
   343→            _ => {}
   344→        }
   345→    }
   346→
   347→    output
   348→}
