     1→// Phase 1: Code Executor
     2→// FV-Lang 코드를 실행하고 결과를 캡처하는 모듈
     3→
     4→use std::process::{Command, Stdio}
     5→use std::time::Instant
     6→
     7→// ============================================================================
     8→// Execution Request/Result Types
     9→// ============================================================================
    10→
    11→struct ExecutionRequest {
    12→    code: String,
    13→    language: String,
    14→    timeout_ms: i32
    15→}
    16→
    17→struct ExecutionResult {
    18→    stdout: String,
    19→    stderr: String,
    20→    exit_code: i32,
    21→    execution_time: f64,
    22→    success: bool
    23→}
    24→
    25→enum ExecutionError {
    26→    CompilationFailed(String),
    27→    RuntimeError(String),
    28→    Timeout,
    29→    IOError(String)
    30→}
    31→
    32→// ============================================================================
    33→// Compiler Interface
    34→// ============================================================================
    35→
    36→struct CompilerConfig {
    37→    name: String,
    38→    version: String,
    39→    path: String,
    40→    flags: Vec<String>
    41→}
    42→
    43→impl CompilerConfig {
    44→    fn for_fvlang() -> CompilerConfig {
    45→        CompilerConfig {
    46→            name: "fvlang".to_string(),
    47→            version: "0.1.0".to_string(),
    48→            path: "fvlang".to_string(),
    49→            flags: vec![
    50→                "--optimize".to_string(),
    51→                "--check".to_string()
    52→            ]
    53→        }
    54→    }
    55→}
    56→
    57→fn compile_fvlang(code: String, compiler: CompilerConfig) -> Result<String, ExecutionError> {
    58→    // 임시 파일에 코드 작성
    59→    let temp_file = "/tmp/sovereign_temp.fl"
    60→
    61→    // FV-Lang 컴파일러 호출
    62→    let output = Command::new(&compiler.path)
    63→        .arg("compile")
    64→        .arg(temp_file)
    65→        .output()
    66→        .map_err(|e| ExecutionError::IOError(format!("Failed to run compiler: {}", e)))?
    67→
    68→    if !output.status.success() {
    69→        let stderr = String::from_utf8_lossy(&output.stderr).to_string()
    70→        return Err(ExecutionError::CompilationFailed(stderr))
    71→    }
    72→
    73→    let stdout = String::from_utf8_lossy(&output.stdout).to_string()
    74→    Ok(stdout)
    75→}
    76→
    77→// ============================================================================
    78→// Sandbox: 격리된 실행 환경
    79→// ============================================================================
    80→
    81→struct SandboxConfig {
    82→    memory_limit_mb: i32,
    83→    cpu_timeout_seconds: i32,
    84→    network_enabled: bool,
    85→    filesystem_read_only: bool
    86→}
    87→
    88→impl SandboxConfig {
    89→    fn default() -> SandboxConfig {
    90→        SandboxConfig {
    91→            memory_limit_mb: 256,
    92→            cpu_timeout_seconds: 10,
    93→            network_enabled: false,
    94→            filesystem_read_only: true
    95→        }
    96→    }
    97→}
    98→
    99→fn run_in_sandbox(executable: String, sandbox: SandboxConfig) -> Result<(String, String, i32), ExecutionError> {
   100→    let start = Instant::now()
   101→
   102→    let output = Command::new(&executable)
   103→        .stdout(Stdio::piped())
   104→        .stderr(Stdio::piped())
   105→        .output()
   106→        .map_err(|e| ExecutionError::IOError(format!("Failed to execute: {}", e)))?
   107→
   108→    let duration = start.elapsed().as_secs_f64() * 1000.0  // ms
   109→
   110→    if duration > (sandbox.cpu_timeout_seconds as f64 * 1000.0) {
   111→        return Err(ExecutionError::Timeout)
   112→    }
   113→
   114→    let stdout = String::from_utf8_lossy(&output.stdout).to_string()
   115→    let stderr = String::from_utf8_lossy(&output.stderr).to_string()
   116→    let exit_code = output.status.code().unwrap_or(-1)
   117→
   118→    Ok((stdout, stderr, exit_code))
   119→}
   120→
   121→// ============================================================================
   122→// Output Capture
   123→// ============================================================================
   124→
   125→struct OutputCapture {
   126→    stdout_buffer: String,
   127→    stderr_buffer: String,
   128→    start_time: Instant
   129→}
   130→
   131→impl OutputCapture {
   132→    fn new() -> OutputCapture {
   133→        OutputCapture {
   134→            stdout_buffer: String::new(),
   135→            stderr_buffer: String::new(),
   136→            start_time: Instant::now()
   137→        }
   138→    }
   139→
   140→    fn append_stdout(&mut self, content: String) {
   141→        self.stdout_buffer.push_str(&content)
   142→    }
   143→
   144→    fn append_stderr(&mut self, content: String) {
   145→        self.stderr_buffer.push_str(&content)
   146→    }
   147→
   148→    fn elapsed_ms(&self) -> f64 {
   149→        self.start_time.elapsed().as_secs_f64() * 1000.0
   150→    }
   151→
   152→    fn finalize(&self) -> (String, String) {
   153→        (self.stdout_buffer.clone(), self.stderr_buffer.clone())
   154→    }
   155→}
   156→
   157→// ============================================================================
   158→// REPL Mode: 대화형 실행
   159→// ============================================================================
   160→
   161→struct REPLContext {
   162→    variables: Map<String, String>,
   163→    functions: Map<String, String>,
   164→    session_history: Vec<ExecutionRequest>
   165→}
   166→
   167→impl REPLContext {
   168→    fn new() -> REPLContext {
   169→        REPLContext {
   170→            variables: Map::new(),
   171→            functions: Map::new(),
   172→            session_history: Vec::new()
   173→        }
   174→    }
   175→
   176→    fn define_variable(&mut self, name: String, value: String) {
   177→        self.variables.insert(name, value)
   178→    }
   179→
   180→    fn define_function(&mut self, name: String, code: String) {
   181→        self.functions.insert(name, code)
   182→    }
   183→
   184→    fn get_context_code(&self) -> String {
   185→        let mut code = String::new()
   186→
   187→        // 정의된 함수들을 코드에 포함
   188→        for (_, func_code) in &self.functions {
   189→            code.push_str(func_code)
   190→            code.push_str("\n")
   191→        }
   192→
   193→        code
   194→    }
   195→
   196→    fn record_execution(&mut self, request: ExecutionRequest) {
   197→        self.session_history.push(request)
   198→    }
   199→}
   200→
   201→// ============================================================================
   202→// Main Executor
   203→// ============================================================================
   204→
   205→struct Executor {
   206→    compiler: CompilerConfig,
   207→    sandbox: SandboxConfig,
   208→    repl_context: Option<REPLContext>
   209→}
   210→
   211→impl Executor {
   212→    fn new() -> Executor {
   213→        Executor {
   214→            compiler: CompilerConfig::for_fvlang(),
   215→            sandbox: SandboxConfig::default(),
   216→            repl_context: None
   217→        }
   218→    }
   219→
   220→    fn enable_repl(&mut self) {
   221→        self.repl_context = Some(REPLContext::new())
   222→    }
   223→
   224→    fn execute(&mut self, request: ExecutionRequest) -> Result<ExecutionResult, ExecutionError> {
   225→        let mut capture = OutputCapture::new()
   226→
   227→        // 1. 컴파일
   228→        let _compiled = compile_fvlang(request.code.clone(), self.compiler.clone())?
   229→
   230→        // 2. 실행
   231→        let (stdout, stderr, exit_code) = run_in_sandbox(
   232→            "fvlang_executable".to_string(),
   233→            self.sandbox.clone()
   234→        )?
   235→
   236→        capture.append_stdout(stdout)
   237→        capture.append_stderr(stderr)
   238→
   239→        let (final_stdout, final_stderr) = capture.finalize()
   240→        let success = exit_code == 0
   241→
   242→        // 3. REPL 모드인 경우 히스토리 저장
   243→        if let Some(ref mut ctx) = self.repl_context {
   244→            ctx.record_execution(request)
   245→        }
   246→
   247→        Ok(ExecutionResult {
   248→            stdout: final_stdout,
   249→            stderr: final_stderr,
   250→            exit_code: exit_code,
   251→            execution_time: capture.elapsed_ms(),
   252→            success: success
   253→        })
   254→    }
   255→
   256→    fn execute_with_context(&mut self, code: String) -> Result<ExecutionResult, ExecutionError> {
   257→        if let Some(ref ctx) = self.repl_context {
   258→            let full_code = format!("{}\n{}", ctx.get_context_code(), code)
   259→            self.execute(ExecutionRequest {
   260→                code: full_code,
   261→                language: "fvlang".to_string(),
   262→                timeout_ms: 10000
   263→            })
   264→        } else {
   265→            self.execute(ExecutionRequest {
   266→                code: code,
   267→                language: "fvlang".to_string(),
   268→                timeout_ms: 10000
   269→            })
   270→        }
   271→    }
   272→}
   273→
   274→// ============================================================================
   275→// Error Handling
   276→// ============================================================================
   277→
   278→fn error_message(error: ExecutionError) -> String {
   279→    match error {
   280→        ExecutionError::CompilationFailed(msg) => {
   281→            format!("Compilation Error:\n{}", msg)
   282→        }
   283→        ExecutionError::RuntimeError(msg) => {
   284→            format!("Runtime Error:\n{}", msg)
   285→        }
   286→        ExecutionError::Timeout => {
   287→            "Error: Execution timeout (>10s)".to_string()
   288→        }
   289→        ExecutionError::IOError(msg) => {
   290→            format!("IO Error:\n{}", msg)
   291→        }
   292→    }
   293→}
   294→
   295→// ============================================================================
   296→// Public API
   297→// ============================================================================
   298→
   299→fn create_executor() -> Executor {
   300→    Executor::new()
   301→}
   302→
   303→fn execute_fvlang_code(code: String) -> Result<ExecutionResult, String> {
   304→    let mut executor = Executor::new()
   305→    executor.enable_repl()
   306→
   307→    match executor.execute_with_context(code) {
   308→        Ok(result) => Ok(result),
   309→        Err(e) => Err(error_message(e))
   310→    }
   311→}
   312→
   313→fn execute_with_timeout(code: String, timeout_ms: i32) -> Result<ExecutionResult, String> {
   314→    let mut executor = Executor::new()
   315→
