   111→struct EnhancedCodeEditor {
   112→    content: String,
   113→    language: String,
   114→    line_numbers: bool,
   115→    syntax_highlighting: bool,
   116→    line_count: i32,
   117→    modified: bool,
   118→    saved_content: String,
   119→    undo_stack: Vec<String>,
   120→    redo_stack: Vec<String>,
   121→    diff: Option<CodeDiff>
   122→}
   123→
   124→impl EnhancedCodeEditor {
   125→    fn new(language: String) -> EnhancedCodeEditor {
   126→        EnhancedCodeEditor {
   127→            content: String::new(),
   128→            language: language,
   129→            line_numbers: true,
   130→            syntax_highlighting: true,
   131→            line_count: 1,
   132→            modified: false,
   133→            saved_content: String::new(),
   134→            undo_stack: Vec::new(),
   135→            redo_stack: Vec::new(),
   136→            diff: None
   137→        }
   138→    }
   139→
   140→    fn set_content(&mut self, content: String) {
   141→        // 변경 사항 저장 (undo용)
   142→        if !self.content.is_empty() {
   143→            self.undo_stack.push(self.content.clone())
   144→        }
   145→
   146→        self.line_count = content.lines().count() as i32
   147→        self.content = content
   148→        self.modified = true
   149→        self.redo_stack.clear()
   150→    }
   151→
   152→    fn undo(&mut self) -> bool {
   153→        if let Some(prev) = self.undo_stack.pop() {
   154→            self.redo_stack.push(self.content.clone())
   155→            self.content = prev
   156→            self.modified = true
   157→            true
   158→        } else {
   159→            false
   160→        }
   161→    }
   162→
   163→    fn redo(&mut self) -> bool {
   164→        if let Some(next) = self.redo_stack.pop() {
   165→            self.undo_stack.push(self.content.clone())
   166→            self.content = next
   167→            self.modified = true
   168→            true
   169→        } else {
   170→            false
   171→        }
   172→    }
   173→
   174→    fn save(&mut self) {
   175→        self.saved_content = self.content.clone()
   176→        self.modified = false
   177→    }
   178→
   179→    fn compute_diff(&mut self) {
   180→        self.diff = Some(CodeDiff::compute(self.saved_content.clone(), self.content.clone()))
   181→    }
   182→
   183→    fn render_with_highlighting(&self) -> String {
   184→        let mut output = String::new()
   185→
   186→        if self.syntax_highlighting {
   187→            for (i, line) in self.content.lines().enumerate() {
   188→                if self.line_numbers {
   189→                    output.push_str(&format!("{:<4} │ ", i + 1))
   190→                }
   191→
   192→                // 문법 강조 적용
   193→                let highlighted = apply_syntax_highlighting(line.to_string())
   194→                output.push_str(&highlighted)
   195→                output.push_str("\n")
   196→            }
   197→        } else {
   198→            for (i, line) in self.content.lines().enumerate() {
   199→                if self.line_numbers {
   200→                    output.push_str(&format!("{:<4} │ ", i + 1))
   201→                }
   202→                output.push_str(line)
   203→                output.push_str("\n")
   204→            }
   205→        }
   206→
   207→        output
   208→    }
   209→
   210→    fn get_stats(&self) -> (i32, i32, bool, i32, i32) {
   211→        let word_count = self.content.split_whitespace().count() as i32
   212→        let char_count = self.content.len() as i32
   213→        (self.line_count, word_count, self.modified, char_count, self.undo_stack.len() as i32)
   214→    }
   215→}
