     4→use std::collections::HashMap
     5→
     6→// ============================================================================
     7→// Cache Structure for Performance
     8→// ============================================================================
     9→
    10→struct ParserCache {
    11→    parsed_documents: HashMap<String, Document>,
    12→    token_cache: HashMap<String, Vec<Token>>,
    13→    cache_hits: i32,
    14→    cache_misses: i32
    15→}
    16→
    17→impl ParserCache {
    18→    fn new() -> ParserCache {
    19→        ParserCache {
    20→            parsed_documents: HashMap::new(),
    21→            token_cache: HashMap::new(),
    22→            cache_hits: 0,
    23→            cache_misses: 0
    24→        }
    25→    }
    26→
    27→    fn get_cached_document(&mut self, file_hash: String) -> Option<Document> {
    28→        if let Some(doc) = self.parsed_documents.get(&file_hash) {
    29→            self.cache_hits = self.cache_hits + 1
    30→            Some(doc.clone())
    31→        } else {
    32→            self.cache_misses = self.cache_misses + 1
    33→            None
    34→        }
    35→    }
    36→
    37→    fn cache_document(&mut self, file_hash: String, doc: Document) {
    38→        self.parsed_documents.insert(file_hash, doc)
    39→    }
    40→
    41→    fn get_cache_stats(&self) -> (i32, i32, f32) {
    42→        let total = self.cache_hits + self.cache_misses
    43→        let hit_rate = if total > 0 {
    44→            (self.cache_hits as f32) / (total as f32) * 100.0
    45→        } else {
    46→            0.0
    47→        }
    48→        (self.cache_hits, self.cache_misses, hit_rate)
    49→    }
    50→}
