    53→// Optimized Tokenizer (한 번의 패스로 처리)
    54→// ============================================================================
    55→
    56→struct TokenStream {
    57→    tokens: Vec<Token>,
    58→    position: usize
    59→}
    60→
    61→impl TokenStream {
    62→    fn new() -> TokenStream {
    63→        TokenStream {
    64→            tokens: Vec::new(),
    65→            position: 0
    66→        }
    67→    }
    68→
    69→    fn add_token(&mut self, token: Token) {
    70→        self.tokens.push(token)
    71→    }
    72→
    73→    fn peek(&self) -> Option<&Token> {
    74→        if self.position < self.tokens.len() {
    75→            Some(&self.tokens[self.position])
    76→        } else {
    77→            None
    78→        }
    79→    }
