### 핵심 코드 스니펫 (38줄)

```fvlang
impl AINodeEngine {
    fn new(session_id: String) -> AINodeEngine {
        AINodeEngine {
            intent_parser: IntentParser::new(),
            code_generator: CodeGenerator::new(),
            executor: Executor::new(),
            history: Vec::new(),
            session_id: session_id
        }
    }

    fn process_intent(&mut self, request: AINodeRequest) -> Result<AINodeResult, String> {
        let start = std::time::Instant::now()

        // Step 1: 자연어 → Intent
        let intent = self.intent_parser.parse(request.user_input.clone())

        if intent.intent_type == IntentType::Unknown {
            return Err(format!(
                "Could not understand: '{}' (confidence: {:.2})",
                request.user_input, intent.confidence
            ))
        }

        // Step 2: Intent → GeneratedCode
        let generated = self.code_generator.generate(intent.clone())?

        // Step 3: GeneratedCode → NodeGraph
        let visualizer = NodeVisualizer::from_generated_code(generated.clone())
        let node_graph = visualizer.graph.clone()
        let html_output = visualizer.render_html()
        let ascii_output = visualizer.render_ascii()

        // Step 4: (선택적) 실행
        let execution_result = if request.auto_execute {
            match execute_fvlang_code(generated.full_code.clone()) {
                Ok(result) => Some(result),
                Err(_) => None
            }
        } else {
            None
        }

        let elapsed = start.elapsed().as_secs_f64() * 1000.0

        let result = AINodeResult {
            intent: intent,
            generated_code: generated,
            node_graph: node_graph,
            execution_result: execution_result,
            html_output: html_output,
            ascii_output: ascii_output,
            processing_time_ms: elapsed
        }

        // 히스토리 저장
        self.history.push(AINodeHistory {
            request: request,
            result: result.clone(),
            timestamp: "2026-04-01".to_string()
        })

        Ok(result)
    }

    fn get_history_summary(&self) -> Vec<String> {
        self.history.iter().map(|h| {
            format!(
                "[{}] '{}' → {} (conf: {:.2}, {:.1}ms)",
                h.timestamp,
                h.request.user_input,
                h.result.generated_code.fn_name,
                h.result.intent.confidence,
                h.result.processing_time_ms
            )
        }).collect()
    }

    fn clear_history(&mut self) {
        self.history.clear()
        self.code_generator.fn_counter = 0
    }
}

// 공개 API: 단순 진입점
fn process_intent(user_input: String) -> Result<AINodeResult, String> {
    let mut engine = AINodeEngine::new("default".to_string())
    engine.process_intent(AINodeRequest {
        user_input: user_input,
        session_id: "default".to_string(),
        auto_execute: false
    })
}

fn process_intent_with_execution(user_input: String) -> Result<AINodeResult, String> {
    let mut engine = AINodeEngine::new("default".to_string())
    engine.process_intent(AINodeRequest {
        user_input: user_input,
        session_id: "default".to_string(),
        auto_execute: true
    })
}
```

### Phase 1 `WorkflowState` 확장 방법

`/data/data/com.termux/files/home/projects/sovereign-workspace/src/phase1/main.fl`의 `WorkflowState` struct에 `ai_node: AINodeEngine` 필드를 추가하고, `WorkflowState::new()`에서 `AINodeEngine::new(session_id.clone())`로 초기화합니다. `WorkflowState`에 `process_natural_language(input: String) -> Result<AINodeResult, String>` 메서드를 추가하면 Phase 2 기능이 기존 워크플로우에 통합됩니다.

